tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "read_transcript",
    "description": "Liest das kanonisch nummerierte Transkript erneut (optional nur den Bereich fromUnit..toUnit, 1-basierte Unit-Nummern). Nutze es, wann immer du etwas nachpruefen willst.",
    "parameters": {
      "type": "object",
      "properties": {
        "fromUnit": {
          "type": [
            "integer",
            "null"
          ],
          "default": null
        },
        "toUnit": {
          "type": [
            "integer",
            "null"
          ],
          "default": null
        }
      }
    }
  },
  {
    "type": "function",
    "name": "validate_draft",
    "description": "Prueft einen Entwurf deterministisch (Schema, Typen, existierende AU-Referenzen, Duplikate) und gibt eine Fehlerliste zurueck \u2014 beliebig oft nutzbar, veraendert nichts.",
    "parameters": {
      "type": "object",
      "properties": {
        "statements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "statement": {
                "type": "string"
              },
              "type": {
                "type": "string"
              },
              "sourceUnitIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "derivation": {
                "type": "string"
              },
              "uncertainty": {
                "type": "string"
              }
            },
            "required": [
              "statement",
              "type",
              "sourceUnitIds",
              "derivation",
              "uncertainty"
            ]
          }
        }
      },
      "required": [
        "statements"
      ]
    }
  },
  {
    "type": "function",
    "name": "submit_result",
    "description": "GENAU EINMAL am Ende: reicht dein Endergebnis ein. Validierung ist HART (Fehlerliste zurueck = nachbessern und erneut einreichen). Erst eine GUELTIGE Einreichung beendet die Aufgabe.",
    "parameters": {
      "type": "object",
      "properties": {
        "statements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "statement": {
                "type": "string"
              },
              "type": {
                "type": "string"
              },
              "sourceUnitIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "derivation": {
                "type": "string"
              },
              "uncertainty": {
                "type": "string"
              }
            },
            "required": [
              "statement",
              "type",
              "sourceUnitIds",
              "derivation",
              "uncertainty"
            ]
          }
        }
      },
      "required": [
        "statements"
      ]
    }
  }
]

